  // 5. Return ! GetIANATimeZoneOffsetNanoseconds(instant.[[Nanoseconds]],
  // timeZone.[[Identifier]]).
  return GetIANATimeZoneOffsetNanoseconds(
      isolate, direct_handle(instant->nanoseconds(), isolate),
      time_zone->time_zone_index());
}

